import itertools, sys, json
L = {71, 97, 54, 56, 44, 158, 45, 58, 82, 135, 113, 117, 86, 40, 12, 185, 63, 50, 111, 72, 90, 109, 61, 13, 92, 60, 91, 35, 114, 94, 105, 26, 15, 51, 102, 118, 76, 32, 108, 23, 22, 134, 83, 43, 64}
L = list(L)

# Precompute all possible triples (a,b,c) with a+b=c and distinct elements
triples = []
for a, b, c in itertools.permutations(L, 3):
    if a + b == c:
        triples.append((a, b, c))

# Build adjacency: for each element, which triples include it
elem_to_triples = {x: [] for x in L}
for t in triples:
    for x in t:
        elem_to_triples[x].append(t)

solution = []
used = set()

def backtrack():
    if len(used) == len(L):
        return True
    # pick an unused element with fewest candidate triples to prune
    candidates = [(len([t for t in elem_to_triples[x] if all(y not in used for y in t)]), x) for x in L if x not in used]
    _, elem = min(candidates)
    for t in elem_to_triples[elem]:
        if any(y in used for y in t):
            continue
        # try this triple
        solution.append(t)
        used.update(t)
        if backtrack():
            return True
        # backtrack
        solution.pop()
        used.difference_update(t)
    return False

found = backtrack()
if found:
    witness = {"polarity": "positive", "evidence": {"path": "execution://witness"}, "data": {"triples": solution}}
    print("WITNESS: " + json.dumps(witness))
else:
    witness = {"polarity": "negative", "evidence": {"path": "execution://witness"}, "basis": "search", "search_exhausted": true, "nodes_explored": null, "method": "backtrack"}
    print("WITNESS: " + json.dumps(witness))

import json
from itertools import combinations

L = {71, 97, 54, 56, 44, 158, 45, 58, 82, 135, 113, 117, 86, 40, 12, 185, 63, 50, 111, 72, 90, 109, 61, 13, 92, 60, 91, 35, 114, 94, 105, 26, 15, 51, 102, 118, 76, 32, 108, 23, 22, 134, 83, 43, 64}

# Pre‑compute all possible triples (a,b,c) with a+b=c
triples = []
for a, b in combinations(L, 2):
    c = a + b
    if c in L and c != a and c != b:
        triples.append((a, b, c))

# Backtracking search for 15 disjoint triples
solution = []
used = set()

def backtrack(start):
    if len(solution) == 15:
        return True
    if start >= len(triples):
        return False
    for i in range(start, len(triples)):
        a, b, c = triples[i]
        if a in used or b in used or c in used:
            continue
        # Choose
        solution.append((a, b, c))
        used.update([a, b, c])
        if backtrack(i + 1):
            return True
        # Undo
        solution.pop()
        used.difference_update([a, b, c])
    return False

found = backtrack(0)

if found:
    witness_data = {"triples": solution}
else:
    witness_data = {"error": "No partition found"}

print('WITNESS: ' + json.dumps({"polarity": "positive" if found else "negative", "evidence": {"path": "execution://witness"}, "data": witness_data}))

